(()=>{
 const D=RoadmapData,key='statics-roadmap-v1';let topic='resultants',saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}if(typeof saved!=='object'||Array.isArray(saved))saved={};
 const persist=()=>{try{localStorage.setItem(key,JSON.stringify(saved));}catch{}},progress=p=>{if(!saved[p.id]||typeof saved[p.id]!=='object')saved[p.id]={index:0,answers:{},checked:{},helped:{},evidenceEligible:true};const v=saved[p.id];for(const name of ['answers','checked','helped'])if(!v[name]||typeof v[name]!=='object')v[name]={};v.index=Math.max(0,Math.min(p.steps.length-1,Math.floor(Number(v.index))||0));v.sigFigs=Number.isInteger(v.sigFigs)&&v.sigFigs>=1&&v.sigFigs<=10?v.sigFigs:3;v.rounding??={};return v;};
 function correct(p,step,answers){const state=progress(p);return D.correct(step,answers,state.rounding[p.steps.indexOf(step)]??state.sigFigs);}
 const diagramPreferences=new Map(),revealedStates=new Map(),fullExamplesOpen=new Set();
 const resultNumber=(value,digits)=>value===0?'0':Number(Number(value).toPrecision(digits)).toString();
 function checkedAnswer(p,s){return s.fields?'<div class="assessment-feedback correct numerical-answer">'+s.fields.map(f=>'<span aria-label="'+M.esc(f.label)+'">'+resultNumber(f.value,progress(p).sigFigs)+'</span>').join('<span aria-hidden="true">, </span>')+'</div>':'<div class="assessment-feedback correct" aria-label="Correct">&#10003;</div>';}
 function visibleGeometry(p){const state=progress(p);return p.steps.flatMap((step,i)=>state.checked[i]&&correct(p,step,state.answers[i]||{})?step.reveals||[]:[]);}

 const diagramId=p=>'roadmapDiagram-'+p.id;
 function diagramItems(p){return [...(p.graph?.items||[]),...visibleGeometry(p)];}
 function earnedMeasurements(p){const state=progress(p);return diagramItems(p).map((item,index)=>({item,index})).filter(({item})=>state.checked[item.measurementStep]&&correct(p,p.steps[item.measurementStep],state.answers[item.measurementStep]||{}));}
 function diagramSettings(p){if(!diagramPreferences.has(p.id))diagramPreferences.set(p.id,{view:p.graph.view,visible:false,plane:'xy',index:0,earned:[]});const v=diagramPreferences.get(p.id),earned=earnedMeasurements(p).map(entry=>entry.index),newIndex=earned.findLast(index=>!v.earned.includes(index));if(newIndex!==undefined){v.visible=true;v.index=newIndex;}if(!earned.includes(v.index))v.index=earned[0]??0;if(!earned.length)v.visible=false;v.earned=earned;return v;}
 function diagramPanel(p){if(!p.graph)return '';const g=p.graph,v=diagramSettings(p),earned=earnedMeasurements(p);return `<div class="roadmap-diagram-tools"><label>View<select id="roadmapGraphView">${['xy','xz','yz','iso'].map(view=>`<option value="${view}" ${v.view===view?'selected':''}>${view==='iso'?'3D projection':view+' plane'}</option>`).join('')}</select></label>${earned.length?`<div id="roadmapEarnedControls" class="earned-measurement-controls"><button id="roadmapMeasurementToggle" aria-pressed="${v.visible}">${v.visible?'Hide':'Show'} measurement layer</button><label>Vector<select id="roadmapMeasureVector">${earned.map(({item,index:i})=>`<option value="${i}" ${i===v.index?'selected':''}>${M.esc(item.label)}</option>`).join('')}</select></label><label>Landing plane<select id="roadmapMeasurePlane">${['xy','xz','yz'].map(plane=>`<option ${v.plane===plane?'selected':''}>${plane}</option>`).join('')}</select></label></div>`:''}</div><svg id="${diagramId(p)}" viewBox="0 0 600 400" role="img" aria-label="Problem geometry and vector arrows with labelled coordinate axes"></svg><p class="diagram-help">${M.esc(g.note||'')}</p><div id="roadmapMeasurements" ${v.visible?'':'hidden'}></div>`;}
 function draw(p){const original=p.graph;if(!original)return;const derived=visibleGeometry(p),signature=JSON.stringify(derived);if(revealedStates.get(p.id)!==signature){GraphScales.refit(diagramId(p));revealedStates.set(p.id,signature);}const g={...original,items:[...original.items,...derived]};const v=diagramSettings(p),item=g.items[v.index],delta=item.end.map((n,i)=>n-item.start[i]),directionOnly=(/direction/.test(item.label)&&!/^r/.test(item.label))||(g.unit!=='m'&&/axis/.test(item.label)),norm=Math.hypot(...delta),drop={xy:2,xz:1,yz:0}[v.plane],landing=item.end.map((n,i)=>i===drop?0:n),display=n=>resultNumber(n,progress(p).sigFigs);Engineering.diagram(diagramId(p),v.view,v.visible?g.items:original.items,g.angles||[],g.unit,v.visible?{index:v.index,plane:v.plane,directionOnly}:null);const panel=$('roadmapMeasurements');if(earnedMeasurements(p).length){$('roadmapMeasureVector').innerHTML=earnedMeasurements(p).map(({item,index})=>'<option value="'+index+'" '+(index===v.index?'selected':'')+'>'+M.esc(item.label)+'</option>').join('');$('roadmapMeasurementToggle').textContent=(v.visible?'Hide':'Show')+' measurement layer';$('roadmapMeasurementToggle').setAttribute('aria-pressed',String(v.visible));}panel.hidden=!v.visible;panel.innerHTML=directionOnly?`<p><strong>${M.esc(item.label)}</strong>: this arrow illustrates direction. Its drawn length is not a force or moment measurement.</p><p>Unit direction: (${delta.map(n=>norm?display(n/norm):0).join(', ')})</p>`:`<h3>Read the geometry: ${M.esc(item.label)}</h3><table><thead><tr><th>Measurement (${M.esc(g.unit)})</th><th>x</th><th>y</th><th>z</th></tr></thead><tbody>${[['Start',item.start],['End',item.end],['Signed components: end minus start',delta],['Plane-projected components',delta.map((n,i)=>i===drop?0:n)],[v.plane+' landing of end',landing]].map(([name,values])=>`<tr><th>${name}</th>${values.map(n=>`<td>${display(n)}</td>`).join('')}</tr>`).join('')}</tbody></table><p><strong>Vector magnitude:</strong> ${display(norm)} ${M.esc(g.unit)}</p><p class="projection-note">Dashed purple lines drop the endpoints onto the ${v.plane} plane. The dashed arrow is the plane projection. Coordinates locate points; signed components measure the vector between them.</p>`;}
 const chosen=()=>D.problems.find(p=>p.group===topic&&p.id===(saved._selected?.[topic]||topic))||D.problems.find(p=>p.group===topic);
 const completed=p=>{const state=progress(p);return !!state.completed||p.steps.every((step,i)=>state.checked[i]&&correct(p,step,state.answers[i]||{}));};
 function selectProblem(id){const p=D.problems.find(p=>p.id===id);if(!p||p.group!==topic||window.examInProgress)return;saved._selected??={};saved._selected[topic]=id;persist();render();}
 function picker(p){const all=D.problems.filter(item=>item.group===topic),types=[...new Map(all.map(item=>[item.familyId||item.id,all.find(candidate=>candidate.id===(item.familyId||item.id))||item])).values()],examples=all.filter(item=>(item.familyId||item.id)===(p.familyId||p.id));const familyDone=item=>all.some(candidate=>(candidate.familyId||candidate.id)===(item.familyId||item.id)&&completed(candidate));return `<article class="panel roadmap-picker"><h2>Choose a problem type</h2><label>Problem type<select id="roadmapProblemType">${types.map(item=>`<option value="${item.id}" ${(item.familyId||item.id)===(p.familyId||p.id)?'selected':''}>${familyDone(item)?'Completed - ':''}${M.esc(item.typeName)}</option>`).join('')}</select></label><label>Example<select id="roadmapExample">${examples.map(item=>`<option value="${item.id}" ${item.id===p.id?'selected':''}>${completed(item)?'Completed - ':''}${item.exampleNumber?'Numerical variation '+(item.exampleNumber+1):'Original example'}</option>`).join('')}</select></label><div class="roadmap-types">${types.map(item=>`<button data-roadmap-problem="${item.id}" aria-pressed="${(item.familyId||item.id)===(p.familyId||p.id)}"><span class="type-check">${familyDone(item)?'&#10003;':''}</span><span>${M.esc(item.typeName)}</span><span class="sr-only">${familyDone(item)?'Completed; select to review or retry':'Not completed'}</span></button>`).join('')}</div><p class="projection-note">Each type saves its own steps in this browser. A green check records completion; you can still select it to review or try again.</p></article>`;}
 function formula(s){const title=s.title.toLowerCase(),norm=v=>mo('|')+v+mo('|'),rv=vector('r','rvector'),fv=vector('F','Fvector');let body='';if(title.includes('normalize'))body=vector('u','uvector')+mo('=')+fraction(rv,norm(rv));else if(title==='build the direction vector')body=taggedVector('r','AB','displacement')+mo('=')+taggedVector('r','B','positionB')+mo('−')+taggedVector('r','A','positionA');else if(title==='construct the cable force')body=fv+mo('=')+mi('F')+taggedVector('u','AB','unitAB');else if(title==='add matching components')body=sub('R','x')+mo('=')+sub('A','x')+mo('+')+sub('B','x')+mo(',')+sub('R','y')+mo('=')+sub('A','y')+mo('+')+sub('B','y');else if(title==='take the scalar projection')body=sub('F','axis')+mo('=')+fv+mo('·')+taggedVector('u','AB','unitAB');else if(title==='project the moment')body=mi('M','axisMomentScalar')+mo('=')+vector('u','axisMomentUnit')+mo('·')+vector('M','axisPointMoment');else if(title.includes('calculate the moment')||title==='calculate the point moment')body=vector('M','momentVector')+mo('=')+vector('r','momentPosition')+mo('×')+vector('F','forceMoment');else if(title==='find the perpendicular arm'||title==='find the perpendicular spacing')body=mi('d',title.includes('spacing')?'coupleArm':'momentArm')+mo('=')+fraction(norm(vector('M',title.includes('spacing')?'coupleVector':'momentVector')),norm(fv));return body?'<div class="math">'+math(body)+'</div>':'';}

 function workedEquation(value){
  const atom=value=>'<mtext>'+M.esc(value)+'</mtext>';
  // Numeric divisions use real stacked fractions; surrounding operators remain uniform.
  const parts=value.split(/([-\u2212]?\d+(?:\.\d+)?\/\d+(?:\.\d+)?)/g);
  return '<div class="math worked-equation">'+math(parts.map(part=>/^[-\u2212]?\d+(?:\.\d+)?\/\d+(?:\.\d+)?$/.test(part)?fraction(...part.split('/').map(atom)):atom(part)).join(''))+'</div>';
 }
 function workedExplanation(s,heading=true){return (heading?'<h3>Worked explanation</h3>':'')+'<ol class="roadmap-worked">'+s.worked.map(row=>'<li><p>'+M.esc(row.text)+'</p>'+row.equations.map(workedEquation).join('')+'</li>').join('')+'</ol>'+(window.TI84?TI84.renderStep(s,progress(chosen()).sigFigs):'');}

 function fullWorkedExample(p){const final=p.steps.filter(step=>step.fields).at(-1);return `<h2>Full worked example: ${M.esc(p.typeName)}</h2><p>Read the whole solution first, then return to the walkthrough to practise each step.</p>${p.steps.map((step,i)=>`<section class="full-worked-stage"><h3>${i+1}. ${M.esc(step.title)}</h3><p>${M.esc(step.why)}</p>${formula(step)}${workedExplanation(step,false)}</section>`).join('')}${final?`<div class="insight"><strong>Last numerical result</strong>${final.fields.map(field=>`<p><strong>${M.esc(field.label)}</strong>: ${resultNumber(field.value,progress(p).sigFigs)}</p>`).join('')}</div>`:''}`;}
 function history(p,state){const completed=p.steps.map((s,i)=>({s,i,answers:state.answers[i]||{}})).filter(({s,i,answers})=>i!==state.index&&state.checked[i]&&correct(p,s,answers));if(!completed.length)return '';return `<article class="panel roadmap-history"><h2>Your checked steps</h2><p class="projection-note">Keep these results beside the current step. Values below are the answers you entered; open a row for the full explanation.</p>${completed.map(({s,i,answers})=>`<details class="history-step"><summary><strong>${i+1}. ${s.title}</strong><span>${s.options?M.esc(s.options[Number(answers.choice)]):s.fields.map((f,j)=>`<b>${M.esc(f.label)}</b> = ${M.esc(answers[j])}`).join(' · ')}${state.helped[i]?' · explanation viewed':''}</span></summary><p>${s.why}</p>${formula(s)}${workedExplanation(s)}<button data-roadmap-step="${i}">Return to step ${i+1}</button></details>`).join('')}</article>`;}
 function render(){const p=chosen(),state=progress(p),s=p.steps[state.index],answers=state.answers[state.index]||{},passed=!!state.checked[state.index]&&correct(p,s,answers);$('roadmap').innerHTML=`${picker(p)}<div class="roadmap-topic"><div><article class="panel"><div class="eyebrow">GUIDED PROBLEM · ${p.title}</div><h2>${M.esc(p.typeName)}: build the solution</h2><p class="position-problem">${p.prompt}</p>${p.ti84Mode?`<p class="projection-note"><strong>Physical TI-84 Plus:</strong> ${p.ti84Mode==='RAD'?'RADIAN':'DEGREE'} mode, FLOAT. Worked solutions include exact calculator entries and stored-variable steps.</p>`:''}${p.sourceImage?`<figure class="source-problem"><img src="${p.sourceImage}" alt="Original diagram for ${M.esc(p.typeName)}"><figcaption>Diagram from your supplied Exam 1 practice PDF. Calculations below are independently verified.</figcaption></figure>`:''}<div class="actions"><button id="roadmapFullExampleToggle" aria-expanded="${fullExamplesOpen.has(p.id)}" aria-controls="roadmapFullExample">${fullExamplesOpen.has(p.id)?'Hide':'Show'} full worked example</button></div><div id="roadmapFullExample" class="full-worked-example" ${fullExamplesOpen.has(p.id)?'':'hidden'}>${fullExamplesOpen.has(p.id)?fullWorkedExample(p):''}</div><label class="roadmap-precision">Significant figures<select id="roadmapSigFigs">${Array.from({length:10},(_,i)=>i+1).map(digits=>`<option value="${digits}" ${digits===state.sigFigs?'selected':''}>${digits}</option>`).join('')}</select></label>${diagramPanel(p)}<div class="roadmap-step-map">${p.steps.map((step,i)=>`<button data-roadmap-step="${i}" ${i>0&&!p.steps.slice(0,i).every((s,j)=>state.checked[j]&&correct(p,s,state.answers[j]||{}))?'disabled':''} aria-current="${i===state.index?'step':'false'}">${state.checked[i]?'✓ ':''}${i+1}. ${step.title}</button>`).join('')}</div><p class="projection-note">Original worked practice. Answers and progress save in this browser only. You may return to earlier steps.</p></article><div id="roadmapHistory">${history(p,state)}</div><article class="panel roadmap-question"><div class="eyebrow">STEP ${state.index+1} / ${p.steps.length}</div><h2>${s.title}</h2><div class="insight"><strong>Why this step?</strong><p>${s.why}</p></div>${formula(s)}<p class="assessment-prompt">${s.question}</p>${s.ti84?`<p class="projection-note">After calculating, store ${s.ti84.rows.map(row=>M.esc(row.label)+' in calculator '+row.store).join('; ')}. This keeps full precision for later steps.</p>`:''}${s.options?`<fieldset class="answer-options"><legend>Choose an answer</legend>${s.options.map((option,i)=>`<label class="answer-option"><input type="radio" name="roadmapChoice" value="${i}" ${Number(answers.choice)===i&&answers.choice!==undefined?'checked':''}><span>${option}</span></label>`).join('')}</fieldset>`:`<div class="position-answer-grid">${s.fields.map((f,i)=>`<label>${f.label}<input data-roadmap-field="${i}" type="number" step="any" value="${M.esc(answers[i]??'')}"></label>`).join('')}</div><p class="projection-note">Accepted tolerance: ${s.fields.map(f=>`${f.label}: ±${f.tolerance}`).join('; ')}.</p>`}<div class="actions"><button id="roadmapCheck" class="primary">Check this step</button><button id="roadmapHintToggle" aria-expanded="false" aria-controls="roadmapHint">Show hint</button><button id="roadmapExplain" aria-expanded="false" aria-controls="roadmapSolution">Show worked explanation</button><button id="roadmapNext" ${passed?'':'disabled'}>${state.index===p.steps.length-1?'Complete problem':'Next step →'}</button></div><div id="roadmapFeedback" role="status">${passed?checkedAnswer(p,s):''}</div><div id="roadmapHint" class="insight" hidden><strong>Formula reminder</strong><p>${M.esc(s.hint.reminder)}</p><strong>Information to use</strong><p>${M.esc(s.hint.inputs)}</p>${/cross|moment vector|point moment|couple vector/i.test(s.title+' '+s.hint.reminder)?Learning.crossReminder:''}</div><div id="roadmapSolution" class="assessment-feedback" hidden></div><div id="roadmapComplete" hidden class="insight"></div><div class="actions roadmap-bottom"><button id="roadmapExplore">Explore this topic in Workspace →</button><button id="roadmapRestart">Start this type again</button>${state.previous?'<button id="roadmapReview">Review last completed attempt</button>':''}</div></article></div></div>`;
  const saveAnswer=(i,value)=>{state.answers[state.index]??={};state.answers[state.index][i]=value;delete state.checked[state.index];delete state.rounding[state.index];for(let j=state.index+1;j<p.steps.length;j++){delete state.checked[j];delete state.rounding[j];}$('roadmapNext').disabled=true;$('roadmapFeedback').innerHTML='';$('roadmapHistory').innerHTML=history(p,state);draw(p);if($('roadmapEarnedControls'))$('roadmapEarnedControls').hidden=!earnedMeasurements(p).length;document.querySelectorAll('[data-roadmap-step]').forEach(button=>button.onclick=()=>{const next=Number(button.dataset.roadmapStep);if(!p.steps.slice(0,next).every((step,i)=>state.checked[i]&&correct(p,step,state.answers[i]||{})))return;state.index=next;persist();render();});persist();window.StudyCoach?.decorate(p,state);};document.querySelectorAll('[data-roadmap-field]').forEach(input=>input.oninput=()=>saveAnswer(input.dataset.roadmapField,input.value));document.querySelectorAll('input[name="roadmapChoice"]').forEach(input=>input.onchange=()=>saveAnswer('choice',Number(input.value)));
  $('roadmapFullExampleToggle').onclick=()=>{const panel=$('roadmapFullExample'),button=$('roadmapFullExampleToggle'),open=!fullExamplesOpen.has(p.id);if(open){fullExamplesOpen.add(p.id);p.steps.forEach((step,i)=>state.helped[i]=true);persist();panel.innerHTML=fullWorkedExample(p);}else fullExamplesOpen.delete(p.id);panel.hidden=!open;button.textContent=(open?'Hide':'Show')+' full worked example';button.setAttribute('aria-expanded',String(open));};
  $('roadmapCheck').onclick=()=>{const passed=correct(p,s,state.answers[state.index]||{}),diagnostic=window.StudyCoach?.onCheck(p,s,state.answers[state.index]||{},passed,state);if(passed){state.checked[state.index]=true;state.rounding[state.index]=state.sigFigs;persist();render();}else{if(window.StudyCoach){persist();}$('roadmapFeedback').innerHTML=`<div class="assessment-feedback incorrect"><strong>Review this step.</strong><p>${M.esc(diagnostic||'Fill in every requested value, including zeros. Keep signs and units consistent.')}</p><p>${s.why}</p>${window.StudyCoach&&state.assisted?'<p class="projection-note">This is now a supported attempt. Finish it to learn; restart later for an independent demonstration.</p>':''}</div>`;}};
  $('roadmapHintToggle').onclick=()=>{const panel=$('roadmapHint'),button=$('roadmapHintToggle');panel.hidden=!panel.hidden;if(!panel.hidden){state.assisted=true;persist();}if(!panel.hidden&&window.StudyCoach){panel.innerHTML=StudyCoach.hintHTML(p,s,state,state.coachHints?.[state.index]||1);StudyCoach.bindHint(p,s,state,persist);persist();}button.textContent=panel.hidden?'Show hint':'Hide hint';button.setAttribute('aria-expanded',String(!panel.hidden));};
  $('roadmapExplain').onclick=()=>{state.helped[state.index]=true;persist();const panel=$('roadmapSolution'),button=$('roadmapExplain');panel.hidden=!panel.hidden;if(!panel.hidden)panel.innerHTML=workedExplanation(s);button.textContent=panel.hidden?'Show worked explanation':'Hide worked explanation';button.setAttribute('aria-expanded',String(!panel.hidden));};$('roadmapNext').onclick=()=>{if(!correct(p,s,state.answers[state.index]||{})||!state.checked[state.index])return;if(state.index<p.steps.length-1){state.index++;persist();render();}else{state.completed=true;persist();window.StudyMastery?.record(p,state);window.StudyCoach?.onComplete(p,state);render();$('roadmapComplete').hidden=false;$('roadmapComplete').textContent='Walkthrough complete. You checked every step'+(Object.values(state.helped).some(Boolean)?' with worked explanations available.':'.')+' Try the Workspace or a timed exam to apply the process independently.';}};
  $('roadmapRestart').onclick=()=>{const done=completed(p),previous=done&&p.steps.every((step,i)=>state.checked[i]&&correct(p,step,state.answers[i]||{}))?JSON.parse(JSON.stringify({index:state.index,answers:state.answers,checked:state.checked,helped:state.helped,rounding:state.rounding,assisted:state.assisted})):state.previous;saved[p.id]={index:0,answers:{},checked:{},helped:{},completed:done,previous,evidenceEligible:true,sigFigs:state.sigFigs,rounding:{}};persist();render();};if(state.previous)$('roadmapReview').onclick=()=>{Object.assign(state,JSON.parse(JSON.stringify(state.previous)));state.evidenceEligible=false;persist();render();};$('roadmapSigFigs').onchange=()=>{state.sigFigs=Number($('roadmapSigFigs').value);persist();render();};if($('roadmapExample'))$('roadmapExample').onchange=()=>selectProblem($('roadmapExample').value);$('roadmapProblemType').onchange=()=>selectProblem($('roadmapProblemType').value);document.querySelectorAll('[data-roadmap-problem]').forEach(button=>button.onclick=()=>selectProblem(button.dataset.roadmapProblem));$('roadmapExplore').onclick=()=>{showView(p.workspace);};document.querySelectorAll('[data-roadmap-topic]').forEach(button=>button.onclick=()=>open(button.dataset.roadmapTopic));document.querySelectorAll('[data-roadmap-step]').forEach(button=>button.onclick=()=>{const next=Number(button.dataset.roadmapStep);if(!p.steps.slice(0,next).every((step,i)=>state.checked[i]&&correct(p,step,state.answers[i]||{})))return;state.index=next;persist();render();});if(p.graph){const settings=diagramSettings(p),redraw=()=>{GraphScales.refit(diagramId(p));draw(p);};$('roadmapGraphView').onchange=()=>{settings.view=$('roadmapGraphView').value;redraw();};if(earnedMeasurements(p).length){$('roadmapMeasurementToggle').onclick=()=>{settings.visible=!settings.visible;$('roadmapMeasurementToggle').textContent=(settings.visible?'Hide':'Show')+' measurement layer';$('roadmapMeasurementToggle').setAttribute('aria-pressed',String(settings.visible));redraw();};$('roadmapMeasureVector').onchange=()=>{settings.index=Number($('roadmapMeasureVector').value);redraw();};$('roadmapMeasurePlane').onchange=()=>{settings.plane=$('roadmapMeasurePlane').value;redraw();};}}draw(p);window.StudyCoach?.decorate(p,state);
 }
 function pTitle(id){return D.problems.find(p=>p.group===id).title+' walkthrough';}
 function open(id){if(window.examInProgress)return;if(!D.problems.some(p=>p.group===id))return;topic=id;showView('roadmap');render();$('pageTitle').textContent=pTitle(id);$('pageDescription').textContent=D.problems.find(p=>p.group===id).description;$('pageCategory').textContent='SOLID MECHANICS ROADMAP / '+pTitle(id).toUpperCase();document.title=pTitle(id)+' | Statics Study Lab';document.querySelectorAll('nav [data-roadmap-topic]').forEach(b=>{const active=b.dataset.roadmapTopic===id;b.setAttribute('aria-current',active?'page':'false');b.classList?.toggle('active',active);});if($('roadmapFolder'))$('roadmapFolder').open=true;}
 window.GuidedRoadmap={open,render,selectProblem};render();
})();
